import { getOrientation } from "../settings/orientation-settings";
import { requestFactorials } from "../worker/worker-client";
import { shapeFactorials } from "./orientation-shape";
import { validateN } from "./validate-n";

/**
 * Returns factorials from 0! through N! as a spill range.
 * @customfunction FACTORIALROW
 * @param n Maximum factorial index.
 * @returns {any[][]} Factorials from 0! through N!.
 */
export async function factorialRow(n: number) {
  validateN(n);

  try {
    const values = await requestFactorials(n);
    const orientation = getOrientation();
    return shapeFactorials(values, orientation);
  } catch {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.notAvailable);
  }
}

CustomFunctions.associate("FACTORIALROW", factorialRow);

CustomFunctions.associate("FACTORIALROW", factorialRow);