import type { ExcelFactorialValue } from "../factorial/factorial-cache";
import { createFactorialWorker } from "./worker-entry";

type PendingRequest = {
  resolve: (values: ExcelFactorialValue[]) => void;
  reject: (error: Error) => void;
};

type WorkerSuccessMessage = {
  requestId: string;
  values: ExcelFactorialValue[];
};

type WorkerErrorMessage = {
  requestId: string;
  error: string;
};

type WorkerMessage = WorkerSuccessMessage | WorkerErrorMessage;

let worker: Worker | undefined;
let nextRequestId = 0;
const pending = new Map<string, PendingRequest>();

function rejectAllPending(error: Error): void {
  for (const request of pending.values()) {
    request.reject(error);
  }

  pending.clear();
}

function handleWorkerMessage(event: MessageEvent<WorkerMessage>): void {
  const data = event.data;
  const request = pending.get(data.requestId);

  if (!request) {
    return;
  }

  pending.delete(data.requestId);

  if ("error" in data && data.error) {
    request.reject(new Error(data.error));
    return;
  }

  request.resolve((data as WorkerSuccessMessage).values);
}

function handleWorkerError(): void {
  rejectAllPending(new Error("Worker failed"));
  worker?.terminate();
  worker = undefined;
}

function getWorker(): Worker {
  if (!worker) {
    worker = createFactorialWorker();
    worker.onmessage = handleWorkerMessage;
    worker.onerror = handleWorkerError;
  }

  return worker;
}

export function requestFactorials(n: number): Promise<ExcelFactorialValue[]> {
  return new Promise((resolve, reject) => {
    const requestId = String(++nextRequestId);
    pending.set(requestId, { resolve, reject });
    getWorker().postMessage({ requestId, n });
  });
}

export function resetWorkerClientForTests(): void {
  worker?.terminate();
  worker = undefined;
  pending.clear();
  nextRequestId = 0;
}
