const maxN = 500;

export function validateN(n: number): void {
  if (!Number.isFinite(n)) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue);
  }

  if (!Number.isInteger(n)) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue);
  }

  if (n < 0 || n > maxN) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidNumber);
  }
}
