import type { ExcelFactorialValue } from "../factorial/factorial-cache";
import type { Orientation } from "../settings/orientation-settings";

export function shapeFactorials(
  values: ExcelFactorialValue[],
  orientation: Orientation
): ExcelFactorialValue[][] {
  if (orientation === "column") {
    return values.map((value) => [value]);
  }

  return [values];
}
